GRANT ALL
ON SCHEMA1.TABLE1
TO USER USER1;

grant all
on schema1.table1
to  user user1,
    user user2,
    user user3;

GRANT SELECT, INSERT
ON TABLE SCHEMA1.TABLE1
TO USER USER1, GROUP GROUP1, ROLE ROLE1;

GRANT SELECT
ON SCHEMA1.TABLE1
TO PUBLIC;

GRANT SELECT
ON SCHEMA1.TABLE1
TO USER USER1, PUBLIC;

GRANT SELECT
ON SCHEMA1.TABLE1
TO USER USER1 WITH GRANT OPTION;
